<script setup lang="ts">
import {onMounted,onUnmounted,ref} from 'vue'
import {ElMessage} from 'element-plus'
import {get,post,api} from '../api'
const loading=ref(false),failed=ref(false),stats=ref<any>({}),seeds=ref<any[]>([]),companies=ref<any[]>([]),candidates=ref<any[]>([]),runs=ref<any[]>([]),total=ref(0),page=ref(1),status=ref(''),selectedCompany=ref<number|undefined>(),tab=ref('candidates'),detail=ref<any>(null)
const search=ref({kind:'industry',query:'具身智能 工厂 客户试点 商业交付',company_id:null as number|null,keywords:[] as string[],start_date:'',end_date:'',domains:[] as string[],provider:'tavily'})
const seedForm=ref({name:'',url:'',source_type:'industry_media',company_id:null as number|null}),seedDialog=ref(false)
const importForm=ref({title:'',url:'',company_id:null as number|null,source_type:'other'}),importDialog=ref(false)
const types=['official_website','wechat_official_account','industry_media','github','arxiv','technical_blog','customer_announcement','government','video','other']
const name=(id:number)=>companies.value.find(c=>c.id===id)?.name||'待人工确认'
async function load(){loading.value=true;failed.value=false;try{const params=new URLSearchParams({offset:String((page.value-1)*30),limit:'30'});if(status.value)params.set('review_status',status.value);if(selectedCompany.value)params.set('company_id',String(selectedCompany.value));const results=await Promise.all(['/coverage','/discovery-seeds','/companies?limit=200','/source-candidates?'+params,'/discovery-runs'].map(get));[stats.value,seeds.value,companies.value]=results;const result=results[3];candidates.value=result.items;total.value=result.total;runs.value=results[4]}catch{failed.value=true}finally{loading.value=false}}
async function autoIngest(){await post('/discovery/ingest',{limit:10});ElMessage.success('自动采集与提取已启动，无需审核；在执行记录查看实际进度');tab.value='runs';await load()}
async function discover(s:any){await post('/discovery-seeds/'+s.id+'/discover');ElMessage.success('发现任务已提交');await load()}
async function runSearch(){await post('/discovery/search',{...search.value,start_date:search.value.start_date||null,end_date:search.value.end_date||null});ElMessage.success('搜索发现已提交');await load()}
async function review(c:any,state:string){await api.patch('/source-candidates/'+c.id+'/review',{review_status:state,company_id:c.company_id,source_type:c.source_type});ElMessage.success(state==='approved'?'已登记为正式来源；尚未采集或生成事件':'已拒绝候选');await load()}
async function collect(c:any){await post('/sources/'+c.source_id+'/fetch');ElMessage.success('已提交正文采集与证据提取，请在任务页查看实际结果')}
async function addSeed(){await post('/discovery-seeds',seedForm.value);seedDialog.value=false;await load()}
async function addImport(){await post('/source-candidates',importForm.value);importDialog.value=false;await load()}
let timer:ReturnType<typeof setInterval>
onMounted(()=>{load();timer=setInterval(()=>{if(runs.value.some(r=>['queued','running'].includes(r.status)))load()},4000)})
onUnmounted(()=>clearInterval(timer))
</script>
<template><div v-loading="loading"><div class="page-heading"><div><div class="eyebrow">INDUSTRY INTELLIGENCE / COVERAGE</div><h1>信息覆盖与来源发现</h1><p>先扩展可审查的来源，再扩展有证据的行业认知。</p></div><div class="actions"><el-button @click="load">刷新</el-button><el-button type="primary" @click="autoIngest">自动采集并提取（10篇）</el-button><el-button @click="importDialog=true">导入文章 URL</el-button><el-button type="primary" @click="seedDialog=true">添加来源库入口</el-button></div></div><el-alert v-if="failed" type="error" title="加载失败，请确认服务运行后刷新"/><div class="notice">{{stats.warning}} 无需人工审核：发现后自动处理文章正文，校验证据并提取事件。归属不清、栏目页和受限来源自动跳过或记录错误；搜索摘要不作为事实证据。</div><div class="stats"><div class="stat" v-for="[label,value] in [['来源库入口',stats.seeds],['发现候选',stats.candidates],['尚未处理',stats.unprocessed],['真实进展事件',stats.events]]"><span>{{label}}</span><strong>{{value??'—'}}</strong></div></div>
<section class="panel"><h2>公开信息搜索</h2><p>支持中英文、公司别名、技术方向、日期和域名。GitHub 无密钥可搜索公开仓库；通用搜索需 Tavily。</p><el-alert v-if="!stats.tavily_configured" type="warning" title="未配置 TAVILY_API_KEY；通用搜索不可用，可使用栏目/sitemap 或 GitHub 公开搜索" :closable="false"/><el-form label-position="top"><div class="toolbar"><el-form-item label="研究方向"><el-select v-model="search.kind" style="width:160px"><el-option v-for="(label,value) in {industry:'行业新闻',company:'企业动态',technology:'技术方向',website:'发现企业官网',github:'发现 GitHub',papers:'发现论文'}" :key="value" :label="label" :value="value"/></el-select></el-form-item><el-form-item label="搜索 Provider"><el-select v-model="search.provider" style="width:150px"><el-option label="Tavily 通用搜索" value="tavily"/><el-option label="GitHub 公开 API" value="github"/></el-select></el-form-item><el-form-item label="研究企业"><el-select v-model="search.company_id" clearable style="width:200px"><el-option v-for="c in companies" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="开始日期"><el-date-picker v-model="search.start_date" type="date" value-format="YYYY-MM-DD" style="width:170px"/></el-form-item><el-form-item label="结束日期"><el-date-picker v-model="search.end_date" type="date" value-format="YYYY-MM-DD" style="width:170px"/></el-form-item></div><el-form-item label="查询词 / 技术方向"><el-input v-model="search.query"/></el-form-item><el-form-item label="扩展关键词（可自定义；未选择时使用前三个默认词）"><el-select v-model="search.keywords" multiple filterable allow-create style="width:100%"><el-option v-for="k in stats.keywords" :key="k" :label="k" :value="k"/></el-select></el-form-item><el-form-item label="限定域名（输入域名并回车，可多个）"><el-select v-model="search.domains" multiple filterable allow-create default-first-option style="width:100%" placeholder="例如 mp.weixin.qq.com 或 arxiv.org"/></el-form-item><el-button type="primary" @click="runSearch">搜索并保存候选</el-button></el-form></section>
<el-tabs v-model="tab"><el-tab-pane label="发现与自动处理" name="candidates"><section class="panel"><div class="toolbar"><el-select v-model="status" clearable placeholder="全部状态" style="width:160px" @change="page=1;load()"><el-option label="未登记" value="pending"/><el-option label="已批准" value="approved"/><el-option label="已拒绝" value="rejected"/></el-select><el-select v-model="selectedCompany" clearable placeholder="全部企业" style="width:220px" @change="page=1;load()"><el-option v-for="c in companies" :key="c.id" :label="c.name" :value="c.id"/></el-select><span>{{total}} 条匹配候选</span></div><div class="claim" v-for="c in candidates" :key="c.id"><div class="section-heading"><h3><a :href="c.url" target="_blank" rel="noopener noreferrer">{{c.title}} ↗</a></h3><span class="pill">{{c.review_status}} · 相关度 {{c.relevance_score}} / 100</span></div><p>{{c.domain}} · {{c.discovered_by}} · {{c.source_trust_level}} · 发现于 {{c.discovered_at}}</p><p>自动处理：{{c.processing_status}} · 决策方式：{{c.decision_method}} · {{c.processing_error||''}}</p><p>来源日期元数据：{{c.published_at||'unknown'}}（未核验） · {{c.source_id?'已识别正式来源 #'+c.source_id:'尚未登记正式来源'}}</p><p>{{c.snippet||'无搜索摘要；需采集正文核验。'}}</p><p>查询：{{c.discovery_query}}</p><div class="toolbar"><el-select v-model="c.company_id" placeholder="企业归属（可选修正）" style="width:220px" :disabled="c.review_status!=='pending'"><el-option v-for="company in companies" :key="company.id" :label="company.name" :value="company.id"/></el-select><el-select v-model="c.source_type" style="width:200px" :disabled="c.review_status!=='pending'"><el-option v-for="t in types" :key="t" :value="t" :label="t"/></el-select><template v-if="c.review_status==='pending'"><el-button type="primary" @click="review(c,'approved')">手动登记（可选）</el-button><el-button @click="review(c,'rejected')">拒绝</el-button></template><el-button v-if="c.review_status==='approved'&&c.source_id" @click="collect(c)">采集正式来源</el-button><el-button @click="detail=c">发现记录</el-button></div></div><el-empty v-if="!candidates.length" description="暂无匹配候选。执行真实搜索或来源库发现。"/><el-pagination v-model:current-page="page" :page-size="30" :total="total" layout="prev,pager,next,total" @current-change="load"/></section></el-tab-pane>
<el-tab-pane label="行业来源库" name="seeds"><section class="panel" v-for="s in seeds" :key="s.id"><div class="section-heading"><h2>{{s.name}}</h2><span class="pill">{{s.last_status}}</span></div><a :href="s.url" target="_blank" rel="noopener noreferrer">{{s.url}} ↗</a><p>{{s.company_id?name(s.company_id):'跨企业行业来源'}} · {{s.source_type}} · {{s.last_checked_at||'尚未检查'}}</p><pre class="error-text" v-if="s.error">{{s.error}}</pre><el-button @click="discover(s)">检查栏目与 sitemap，发现候选</el-button></section></el-tab-pane>
<el-tab-pane label="发现执行记录" name="runs"><section class="panel" v-for="r in runs" :key="r.id"><h3>#{{r.id}} {{r.kind}} · {{r.status}}</h3><p>{{r.created_at}} → {{r.finished_at||'执行中'}}</p><pre>{{JSON.stringify(r.parameters,null,2)}}</pre><pre v-if="r.error" class="error-text">{{r.error}}</pre><pre>{{JSON.stringify(r.result,null,2)}}</pre></section><el-empty v-if="!runs.length" description="暂无发现任务"/></el-tab-pane></el-tabs>
<el-dialog v-model="seedDialog" title="添加栏目 / sitemap 来源库入口"><el-form label-position="top"><el-form-item label="名称"><el-input v-model="seedForm.name"/></el-form-item><el-form-item label="公开栏目或 sitemap URL"><el-input v-model="seedForm.url"/></el-form-item><el-form-item label="可选企业归属"><el-select v-model="seedForm.company_id" clearable><el-option v-for="c in companies" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="来源类型"><el-select v-model="seedForm.source_type"><el-option v-for="t in types" :key="t" :label="t" :value="t"/></el-select></el-form-item><el-button @click="addSeed">保存</el-button></el-form></el-dialog>
<el-dialog v-model="importDialog" title="导入公开文章（先进入未登记候选）"><el-form label-position="top"><el-form-item label="标题"><el-input v-model="importForm.title"/></el-form-item><el-form-item label="URL"><el-input v-model="importForm.url"/></el-form-item><el-form-item label="可选企业"><el-select v-model="importForm.company_id" clearable><el-option v-for="c in companies" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="来源类型"><el-select v-model="importForm.source_type"><el-option v-for="t in types" :key="t" :label="t" :value="t"/></el-select></el-form-item><el-button type="primary" @click="addImport">提交候选</el-button></el-form></el-dialog>
<el-dialog :model-value="!!detail" @close="detail=null" title="来源发现记录"><pre>{{JSON.stringify(detail?.discovery_history,null,2)}}</pre></el-dialog></div></template>
